#!/usr/bin/env python3
"""Prueba (28-oct-2026) de las hojas del emprendimiento de la Agenda para tejedoras: pedidos con cuentas, contactos, gastos, proyectos por tejer y números del mes.
Uso: con un servidor local en el puerto 8765:  /usr/bin/python3 herramientas/pruebas/probar_agenda_negocio.py [carpeta_capturas]"""
import sys, json, datetime, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from agenda_util import *
T = Prueba(); CAP = sys.argv[1] if len(sys.argv) > 1 else None
def cap(pg, n):
    if CAP: os.makedirs(CAP, exist_ok=True); pg.screenshot(path=os.path.join(CAP, n))
def guardado(pg): return json.loads(pg.evaluate("localStorage.getItem('rosinaAgenda') || '{}'"))
def meta(pg, tabla, r): return pg.inner_text('#%s tr[data-fila="%d"] .ficha-meta' % (tabla, r))
h = datetime.date.today()
with sync_playwright() as p:
    b = p.chromium.launch(executable_path=CHROMIUM, args=['--no-sandbox'])
    # pedidos
    ctx = contexto(b, 390); pg = abrir(ctx, 'control-pedidos')
    ids = ['cliente', 'telefono', 'direccion', 'pedido', 'cantidad', 'valorunidad', 'precio', 'costoenvio', 'totalcompra', 'abono', 'saldo', 'reserva', 'entrega', 'envio', 'medio', 'forma', 'estado', 'obs']
    T.v('pedidos: tiene todas las preguntas pedidas', all(pg.locator('#ag-p1-' + i).count() == 1 for i in ids), [i for i in ids if pg.locator('#ag-p1-' + i).count() != 1])
    # Control de pedidos por secciones (29-oct-2026, pedido de Sara)
    T.v('pedidos: cuatro secciones (cliente, producto, precio y pago, envío)', pg.evaluate("[...document.querySelectorAll('#tabla-pedidos tr[data-fila=\"1\"] .ficha-seccion span')].map(e => e.textContent)") == ['👤 Datos del cliente', '🧶 Producto y detalles adicionales', '💰 Precio y pago', '🚚 Datos y medio de envío'])
    T.v('pedidos: los campos quedan dentro de su sección', pg.evaluate("""(() => { const tds = [...document.querySelectorAll('#tabla-pedidos tr[data-fila="1"] > td')]; let sec = '', m = {}; tds.forEach(td => { if (td.classList.contains('ficha-seccion')) sec = td.textContent; else if (td.dataset.col) m[td.dataset.col] = sec; }); return m.cliente.includes('cliente') && m.telefono.includes('cliente') && m.pedido.includes('Producto') && m.obs.includes('Producto') && m.estado.includes('Producto') && m.entrega.includes('Producto') && m.cantidad.includes('Precio') && m.valorunidad.includes('Precio') && m.costoenvio.includes('Precio') && m.totalcompra.includes('Precio') && m.abono.includes('Precio') && m.saldo.includes('Precio') && m.medio.includes('Precio') && m.direccion.includes('envío') && m.forma.includes('envío') && m.envio.includes('envío'); })()"""))
    T.v('pedidos: cantidad es una lista de números del 1 al 20', pg.evaluate("[...document.querySelectorAll('#ag-p1-cantidad option')].map(o => o.value).join(',')") == ',' + ','.join(str(i) for i in range(1, 21)))
    T.v('medio de pago y forma de envío son listas', pg.evaluate("document.getElementById('ag-p1-medio').tagName") == 'SELECT' and pg.evaluate("document.getElementById('ag-p1-forma').tagName") == 'SELECT')
    pg.fill('#ag-p1-cliente', 'Ana María'); pg.fill('#ag-p1-telefono', '300 123 4567'); pg.fill('#ag-p1-direccion', 'Calle 10 #5-37, Villamaría'); pg.fill('#ag-p1-pedido', 'Oso de 15 cm')
    pg.select_option('#ag-p1-cantidad', '3'); pg.fill('#ag-p1-valorunidad', '$85.000'); pg.fill('#ag-p1-costoenvio', '18000'); pg.fill('#ag-p1-abono', '100000'); pg.wait_for_timeout(300)
    T.v('«Valor total» ya no se ve (era lo mismo que «Total compra»), pero se guarda calculado (3 × $85.000 = $255.000)', pg.input_value('#ag-p1-precio') == '$255.000' and not pg.locator('#ag-p1-precio').is_visible(), pg.input_value('#ag-p1-precio'))
    T.v('solo queda un «Total compra» entre las preguntas del pedido', pg.evaluate("[...document.querySelectorAll('#tabla-pedidos tr[data-fila=\"1\"] td[data-label]')].filter(td => td.offsetParent !== null && /total/i.test(td.dataset.label)).map(td => td.dataset.label)") == ['Total de la compra'], pg.evaluate("[...document.querySelectorAll('#tabla-pedidos tr[data-fila=\"1\"] td[data-label]')].filter(td => td.offsetParent !== null && /total/i.test(td.dataset.label)).map(td => td.dataset.label)"))
    T.v('el total de la compra suma el envío ($273.000)', pg.input_value('#ag-p1-totalcompra') == '$273.000', pg.input_value('#ag-p1-totalcompra'))
    T.v('el saldo pendiente resta lo abonado ($173.000)', pg.input_value('#ag-p1-saldo') == '$173.000', pg.input_value('#ag-p1-saldo'))
    T.v('la ficha cerrada dice cuánto debe', 'Debe $173.000' in meta(pg, 'tabla-pedidos', 1), meta(pg, 'tabla-pedidos', 1))
    T.v('arriba se resume lo por cobrar', 'Por cobrar: $173.000' in pg.inner_text('#control-pedidos .resumen-pedidos'), pg.inner_text('#control-pedidos .resumen-pedidos'))
    pg.fill('#ag-p1-abono', '273000'); pg.wait_for_timeout(300)
    pg.fill('#ag-p1-totalcompra', '$100.000'); pg.wait_for_timeout(300)
    pg.fill('#ag-p1-totalcompra', '$300.000'); pg.wait_for_timeout(300)
    T.v('total escrito a mano: saldo = total − abonado y valor de productos = total − envío', pg.input_value('#ag-p1-saldo') == '$27.000' and pg.input_value('#ag-p1-precio') == '$282.000', (pg.input_value('#ag-p1-saldo'), pg.input_value('#ag-p1-precio')))
    pg.fill('#ag-p1-costoenvio', '10000'); pg.wait_for_timeout(300)
    T.v('y al cambiar el envío el total se ajusta ($292.000)', pg.input_value('#ag-p1-totalcompra') == '$292.000', pg.input_value('#ag-p1-totalcompra'))
    pg.fill('#ag-p1-costoenvio', '18000'); pg.select_option('#ag-p1-cantidad', '3'); pg.fill('#ag-p1-valorunidad', '$85.000'); pg.fill('#ag-p1-abono', '273000'); pg.wait_for_timeout(300)
    T.v('al pagar todo el saldo queda en $0 y la ficha dice «Pagado»', pg.input_value('#ag-p1-saldo') == '$0' and 'Pagado' in meta(pg, 'tabla-pedidos', 1), pg.input_value('#ag-p1-saldo'))
    T.v('se guarda con los nombres de siempre y los nuevos', guardado(pg).get('ag-p1-saldo') == '$0' and guardado(pg).get('ag-p1-telefono') == '300 123 4567')
    T.v('el teléfono trae el enlace de WhatsApp', pg.evaluate("document.querySelector('#ag-p1-telefono').parentNode.querySelector('.wa-link').href") == 'https://wa.me/573001234567', pg.evaluate("document.querySelector('#ag-p1-telefono').parentNode.querySelector('.wa-link').href"))
    pg.fill('#ag-p1-envio', (h + datetime.timedelta(days=2)).strftime('%d/%m/%Y')); pg.wait_for_timeout(300)
    ev = pg.evaluate("window.lrAgenda.eventos().filter(e => e.clave.startsWith('pedidoEnvio')).map(e => e.titulo)")
    T.v('la fecha de envío llega al calendario como «Envío: …»', len(ev) == 1 and ev[0].startswith('Envío: Oso de 15 cm'), ev)
    cap(pg, 'negocio-pedidos-390.png')
    T.v('sin desplazamiento horizontal', pg.evaluate("document.documentElement.scrollWidth <= innerWidth + 1"))
    T.v('sin errores de JavaScript', not pg.errs, pg.errs[:2]); ctx.close()
    # un pedido de antes (solo precio y abono) no se pisa
    ctx = contexto(b, 1280, datos={'ag-p1-cliente': 'Sara', 'ag-p1-precio': '$50.000', 'ag-p1-abono': '$20.000'}); pg = abrir(ctx, 'control-pedidos')
    pg.click('#tabla-pedidos tr[data-fila="1"] .ficha-cab'); pg.fill('#ag-p1-observ' if False else '#ag-p1-obs', 'Entregar en la tarde'); pg.wait_for_timeout(300)
    T.v('un pedido de antes conserva su precio y abono', pg.input_value('#ag-p1-precio') == '$50.000' and pg.input_value('#ag-p1-abono') == '$20.000')
    pg.fill('#ag-p1-abono', '$30.000'); pg.wait_for_timeout(300)
    T.v('y al cambiar el abono calcula el total de la compra y el saldo', pg.input_value('#ag-p1-totalcompra') == '$50.000' and pg.input_value('#ag-p1-saldo') == '$20.000', pg.input_value('#ag-p1-saldo'))
    T.v('sin errores de JavaScript', not pg.errs, pg.errs[:2]); ctx.close()
    # la clienta de un pedido queda sola en la hoja de clientas
    ctx = contexto(b, 1280); pg = abrir(ctx, 'control-pedidos')
    def esc(id_, v): pg.evaluate("([id, v]) => { const e = document.getElementById(id); e.value = v; e.dispatchEvent(new Event('input', {bubbles: true})); e.dispatchEvent(new Event('change', {bubbles: true})); }", [id_, v])
    val = lambda id_: pg.input_value('#' + id_)
    esc('ag-p1-cliente', 'Ana María'); esc('ag-p1-telefono', '300 123 4567'); pg.wait_for_timeout(300)
    T.v('al escribir el nombre en un pedido, la clienta queda en la hoja de clientas con su WhatsApp y la fecha de hoy', val('ag-cl1-nombre') == 'Ana María' and val('ag-cl1-whatsapp') == '300 123 4567' and val('ag-cl1-desde') == datetime.date.today().strftime('%d/%m/%Y'), (val('ag-cl1-nombre'), val('ag-cl1-whatsapp'), val('ag-cl1-desde')))
    T.v('y se guarda con los nombres de siempre', guardado(pg).get('ag-cl1-nombre') == 'Ana María' and guardado(pg).get('ag-cl1-whatsapp') == '300 123 4567')
    esc('ag-p2-cliente', 'ana maria'); pg.wait_for_timeout(300)
    T.v('la misma clienta (aunque cambien mayúsculas o tildes) no se repite', val('ag-cl2-nombre') == '', val('ag-cl2-nombre'))
    esc('ag-p3-cliente', 'Luisa'); pg.wait_for_timeout(300)
    T.v('otra clienta se agrega en el siguiente renglón', val('ag-cl2-nombre') == 'Luisa' and val('ag-cl2-whatsapp') == '', val('ag-cl2-nombre'))
    esc('ag-p3-telefono', '310 555 0000'); pg.wait_for_timeout(300)
    T.v('si luego se escribe el teléfono, se le completa el WhatsApp sin duplicarla', val('ag-cl2-whatsapp') == '310 555 0000' and val('ag-cl3-nombre') == '', (val('ag-cl2-whatsapp'), val('ag-cl3-nombre')))
    esc('ag-p4-telefono', '3105550000'); esc('ag-p4-cliente', 'Otra Persona'); pg.wait_for_timeout(300)
    T.v('el mismo teléfono (aunque lo escriban distinto) es la misma clienta', val('ag-cl3-nombre') == '', val('ag-cl3-nombre'))
    pg.evaluate("window.lrFichas.refrescar()"); pg.wait_for_timeout(300)
    nombres = pg.evaluate("[...document.querySelectorAll('#tabla-clientas tr.ficha .ficha-titulo')].map(e => e.textContent)")
    T.v('en la hoja de clientas se ven Ana María y Luisa', 'Ana María' in nombres and 'Luisa' in nombres, nombres)
    T.v('sin errores de JavaScript', not pg.errs, pg.errs[:2]); ctx.close()
    # contactos
    ctx = contexto(b, 390); pg = abrir(ctx, 'contactos')
    tipos = pg.evaluate("[...document.querySelectorAll('#ag-co1-tipo option')].map(o => o.textContent).slice(1)")
    T.v('contactos: nombre, quién es, teléfono, correo y redes', all(pg.locator('#ag-co1-' + c).count() == 1 for c in ['nombre', 'tipo', 'telefono', 'correo', 'redes']) and 'Proveedor' in tipos and 'Maestra o maestro' in tipos and 'Amiga o amigo tejedor' in tipos, tipos)
    pg.fill('#ag-co1-nombre', 'Doña Marta'); pg.select_option('#ag-co1-tipo', 'Proveedor'); pg.fill('#ag-co1-telefono', '3101234567'); pg.fill('#ag-co1-correo', 'marta@correo.co'); pg.fill('#ag-co1-redes', '@martalanas en Instagram'); pg.wait_for_timeout(300)
    T.v('queda en la lista con su tipo y teléfono, y con enlace de WhatsApp', 'Proveedor' in meta(pg, 'tabla-contactos', 1) and pg.evaluate("document.querySelector('#ag-co1-telefono').parentNode.querySelector('.wa-link').href") == 'https://wa.me/573101234567')
    T.v('sin errores de JavaScript', not pg.errs, pg.errs[:2]); ctx.close()
    # proyectos por tejer con avance
    ctx = contexto(b, 390); pg = abrir(ctx, 'proyectos-fila')
    T.v('proyectos por tejer: la hoja se llama así y tiene avance con fecha', 'Proyectos por tejer' in pg.inner_text('#proyectos-fila header h3') and pg.locator('#ag-f1-avance').count() == 1)
    pg.fill('#ag-f1-proyecto', 'Manta de bebé'); pg.click('#proyectos-fila .avance-btn'); pg.keyboard.type('Terminé el cuadro 3'); pg.wait_for_timeout(300)
    hoy = h.strftime('%d/%m/%Y')
    T.v('«Anotar avance de hoy» pone la fecha y deja escribir', pg.input_value('#ag-f1-avance') == hoy + ' — Terminé el cuadro 3', pg.input_value('#ag-f1-avance'))
    pg.click('#proyectos-fila .avance-btn'); pg.keyboard.type('Cuadro 4'); pg.wait_for_timeout(300)
    T.v('cada avance va en su renglón y la ficha muestra el último', pg.input_value('#ag-f1-avance').count('\n') == 1 and 'Avance ' + h.strftime('%d/%m') in meta(pg, 'tabla-fila', 1), meta(pg, 'tabla-fila', 1))
    ctx.close()
    # gastos por mes
    ant = h.replace(day=1) - datetime.timedelta(days=1)
    datos = {'ag-gs1-fecha': h.strftime('%d/%m/%Y'), 'ag-gs1-categoria': 'Materiales', 'ag-gs1-detalle': 'Lana', 'ag-gs1-valor': '$40.000',
             'ag-gs2-fecha': h.strftime('%d/%m/%Y'), 'ag-gs2-categoria': 'Transporte', 'ag-gs2-detalle': 'Bus a la feria', 'ag-gs2-valor': '$10.000',
             'ag-gs3-fecha': ant.strftime('%d/%m/%Y'), 'ag-gs3-categoria': 'Ferias y mercados', 'ag-gs3-detalle': 'Puesto', 'ag-gs3-valor': '$30.000'}
    ctx = contexto(b, 390, datos=datos); pg = abrir(ctx, 'gastos-negocio')
    vis = "[...document.querySelectorAll('#tabla-gastos tr.ficha')].filter(x => !x.hidden && !x.classList.contains('fuera-mes')).length"
    T.v('gastos: el mes actual muestra sus dos gastos y suma $50.000', '$50.000' in pg.inner_text('#totales-gastos') and pg.evaluate(vis) == 2, pg.inner_text('#totales-gastos'))
    T.v('los totales dicen en qué se fue más (Materiales)', 'Materiales' in pg.inner_text('#totales-gastos') and '$40.000' in pg.inner_text('#totales-gastos'))
    pg.select_option('#gs-mes', str(ant.year * 100 + ant.month)); pg.wait_for_timeout(200)
    T.v('el mes anterior muestra su gasto y su total ($30.000)', '$30.000' in pg.inner_text('#totales-gastos') and pg.evaluate(vis) == 1)
    cap(pg, 'negocio-gastos-390.png')
    T.v('sin errores de JavaScript', not pg.errs, pg.errs[:2]); ctx.close(); b.close()
T.fin()
